<?php
$fmt=function($v,$d=0){return number_format((float)$v,$d,',','.');};
$areaName='Semua area yang diizinkan';$areaNames=array();foreach($branches as $b){$areaNames[$b['SpbbID']]=$b['SpbbName'];if((int)$b['SpbbID']===$selected_area)$areaName=$b['SpbbName'];}
$types=array();foreach($dashboard_vessels as $v)$types[$v['SpbbID'].'/'.mb_strtolower(trim($v['VesselName']))]=$v['VesselType'];
$byType=array();
$byShip=array();
$actual=array();
foreach ($stock['journal'] as $movement) {
    if ($movement['type']!=='OUT') continue;
    $volume=abs((float)$movement['quantity']);
    $name=$movement['vessel'];
    $company=$movement['company'];
    $type=$types[$movement['area'].'/'.mb_strtolower(trim($name))]??'Belum diklasifikasi';
    $type=$type?:'Belum diklasifikasi';
    $byType[$type]=($byType[$type]??0)+$volume;
    $byShip[$name]=($byShip[$name]??0)+$volume;
    $key=mb_strtolower(trim($name).'/'.trim($company));
    if (!isset($actual[$key])) $actual[$key]=array('VesselName'=>$name,'CompanyName'=>$company,'Allocated'=>0,'Purchased'=>0,'Booked'=>0,'Actual'=>0);
    $actual[$key]['Actual']+=$volume;
}
foreach($monitoring as $r){$key=mb_strtolower(trim($r['VesselName']).'/'.trim($r['CompanyName']));if(!isset($actual[$key]))$actual[$key]=array('VesselName'=>$r['VesselName'],'CompanyName'=>$r['CompanyName'],'Allocated'=>0,'Purchased'=>0,'Booked'=>0,'Actual'=>0);foreach(array('Allocated','Purchased','Booked') as $k)$actual[$key][$k]+=$r[$k];}
$quota=array_sum(array_column($actual,'Allocated'));$days=(new DateTime($start))->diff(new DateTime($end))->days+1;arsort($byShip);$year=(int)substr($start,0,4);$activeMonth=substr($start,0,7)===substr($end,0,7)?(int)substr($start,5,2):0;$months=array('Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des');
?>
