<script>
(function(){'use strict';var form=document.getElementById('dashboard-period'),year=document.getElementById('filterYear');document.getElementById('filter_spbb').addEventListener('change',function(){form.submit();});year.addEventListener('change',function(){var u=new URL(window.location.href),y=Number(year.value),m=Number(form.elements.start.value.slice(5,7))||1;u.searchParams.set('start',y+'-'+String(m).padStart(2,'0')+'-01');u.searchParams.set('end',y+'-'+String(m).padStart(2,'0')+'-'+new Date(y,m,0).getDate());window.location.assign(u.toString());});
if(typeof Chart==='undefined')return;var types=<?= json_encode($byType,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,ships=<?= json_encode($byShip,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
